#if defined(XRT_FEATURE_UNICODE) || \
	defined(XRT_FEATURE_X509_NAME)
#ifndef XRT_INTERNAL_CHARSET_H
#define XRT_INTERNAL_CHARSET_H




#if defined(XRT_FEATURE_UNICODE)

/* 内部解码结果包含替换模式应消费的最大子部件长度。 */
typedef struct xrt_utf_decode {
	xutfstatus Status;
	uint32 Scalar;
	size_t Read;
} xrt_utf_decode;



/* 严格解码一个 UTF-8 标量。 */
xrt_utf_decode __xrtUtf8Decode(const unsigned char* pText, size_t iSize);



/* 严格解码一个 UTF-16 标量。 */
xrt_utf_decode __xrtUtf16Decode(const uint16* pText, size_t iSize);



/* 严格解码一个 UTF-32 标量。 */
xrt_utf_decode __xrtUtf32Decode(const uint32* pText, size_t iSize);



/* 无错误副作用地返回 UTF-8 编码长度并可写出结果。 */
size_t __xrtUtf8Encode(uint32 iScalar, unsigned char* pOutput);



/* 无错误副作用地返回 UTF-16 编码长度并可写出结果。 */
size_t __xrtUtf16Encode(uint32 iScalar, uint16* pOutput);



/* 设置带错误位置的 Unicode 值错误。 */
void __xrtUtfSetInvalid(cstr sOperation, size_t iOffset);



/* 设置 Unicode 转换大小溢出错误。 */
void __xrtUtfSetOverflow(cstr sOperation);

#endif



#if defined(XRT_FEATURE_CHARSET)

/* 按显式字节序读取 16 位码元，避免未对齐访问并供转码与检测共用。 */
static inline uint16 __xrtCharsetRead16(
	const unsigned char* pData,
	bool bBigEndian
)
{
	if ( bBigEndian ) {
		return (uint16)(((uint16)pData[0] << 8) | (uint16)pData[1]);
	}
	return __xrtReadLe16(pData);
}



/* 按显式字节序读取 32 位码元，避免未对齐访问并供转码与检测共用。 */
static inline uint32 __xrtCharsetRead32(
	const unsigned char* pData,
	bool bBigEndian
)
{
	if ( bBigEndian ) {
		return ((uint32)pData[0] << 24) | ((uint32)pData[1] << 16) |
			((uint32)pData[2] << 8) | (uint32)pData[3];
	}
	return __xrtReadLe32(pData);
}

#endif

#endif
#endif


/* ========================================================================== */
/* internal: src/internal/xrt_string.h */
/* ========================================================================== */

#if defined(XRT_FEATURE_STRING) || \
	defined(XRT_FEATURE_TEMPLATE_CORE)
#ifndef XRT_INTERNAL_STRING_H
#define XRT_INTERNAL_STRING_H




#if defined(XRT_FEATURE_STRING)

/* 判断一个字节是否属于 XRT 统一的 ASCII 空白集合。 */
static inline bool __xrtStrAsciiSpace(unsigned char iByte)
{
	return (iByte == (unsigned char)' ') || (iByte == (unsigned char)'\t') ||
		(iByte == (unsigned char)'\r') || (iByte == (unsigned char)'\n') ||
		(iByte == (unsigned char)'\v') || (iByte == (unsigned char)'\f');
}



/* 检查字符串视图的指针与长度组合是否合法。 */
static inline bool __xrtStrViewValid(xstrview Text)
{
	if ( (Text.Data == NULL) && (Text.Size != 0) ) {
		__xrtErrorSetInvalidArgument();
		return false;
	}
	return true;
}



/* 返回 ASCII 小写字节，不受进程区域设置影响。 */
static inline unsigned char __xrtStrAsciiLower(unsigned char iByte)
{
	if ( (iByte >= (unsigned char)'A') && (iByte <= (unsigned char)'Z') ) {
		return (unsigned char)(iByte + ((unsigned char)'a' - (unsigned char)'A'));
	}
	return iByte;
}



/* 设置字符串模块的结构化值错误。 */
static inline void __xrtStrSetValueError(int32 iCode, cstr sOperation, cstr sMessage)
{
	xerrordesc tDesc;
	xerror* pError;

	memset(&tDesc, 0, sizeof(tDesc));
	tDesc.Kind = XERR_VALUE;
	tDesc.Domain = "xrt.string";
	tDesc.Code = iCode;
	tDesc.Operation = sOperation;
	tDesc.Message = sMessage;
	pError = xrtErrorBuild(&tDesc);
	if ( pError != NULL ) {
		__xrtErrorSetOwned(pError);
	}
}

#endif

#endif
#endif


