/* 当前记录视图借用 Feed 或 Scratch，直到调用完成接口。 */
typedef struct xtlssessionrecord {
	xtlsrecordtype Type;
	xbytesview Data;
	bool Protected;
} xtlssessionrecord;



/* KeyUpdate 的派生结果只在密文成功排队后提交到活动会话。 */
typedef struct xtlssessionupdate {
	xtlsrecordkey ReadKey;
	xtlsrecordkey WriteKey;
	uint8 ReadTraffic[XTLS_TRANSCRIPT_HASH_MAX_SIZE];
	uint8 WriteTraffic[XTLS_TRANSCRIPT_HASH_MAX_SIZE];
	uint8 Message[XTLS_HANDSHAKE_HEADER_SIZE + 1u];
	size_t MessageSize;
} xtlssessionupdate;



/* 角色清理过程释放尾部状态持有的共享资源，不释放会话本体。 */
typedef void (*xtlssessioncleanproc)(
	xtlssession* pSession,
	ptr pRole
);



/* 会话仅由所属线程或 Worker 驱动，不在内部增加锁。 */
struct xtlssession {
	xtlscontext* Context;
	xnetbuf Feed;
	xnetbuf Send;
	xnetbuf Plain;
	xnetbuf Scratch;
	xtlsrecordkey ReadKey;
	xtlsrecordkey WriteKey;
	xtlssessionrecord Record;
	size_t RecordSize;
	xtlsrole Role;
	xtlsstate State;
	xtlsversion Version;
	xtlscipher Cipher;
	uint32 Wait;
	bool RecordPending;
	bool CloseSent;
	bool CloseReceived;
	bool TransportEof;
	bool FatalSent;
	bool PeerAlertSet;
	xbytesview Protocol;
	xtlsalertlevel PeerAlertLevel;
	xtlsalert PeerAlert;
	size_t AllocationSize;
	xtlssessioncleanproc Clean;
	/* 角色提供现有 KeyUpdate 入口，公共记录层不依赖客户端/服务端模块。 */
	xtlsresult (*KeyUpdate)(xtlssession* pSession, xtlskeyupdate Request);
};



/* 为客户端和服务端专用入口创建公共会话本体，不预分配队列块。 */
xtlssession* __xrtTlsSessionCreate(
	const xtlscontext* pContext,
	xnetbufpool* pPool,
	xtlsrole Role
);



/* 以一次精确分配创建会话及角色尾部状态。 */
