void __xrtCoEntry(xcoro* pCo);



/* 完成协程并执行全部清理过程。 */
void __xrtCoFinish(xcoro* pCo, xcoroterm Term);



/* 在所属宿主线程栈上完成尚未进入用户过程的协程。 */
void __xrtCoFinishHost(xcoro* pCo, xcoroterm Term);



/* 释放已经从全部外部所有者和调度结构中脱离的协程。 */
void __xrtCoFree(xcoro* pCo);



