/* 构建并安装带稳定元数据和可选原因链的结构化错误。 */
void __xrtErrorSetDetail(
	xerrkind Kind,
	cstr sDomain,
	int32 iCode,
	cstr sOperation,
	cstr sMessage,
	const xerror* pCause
)
{
	xerrordesc Desc;
	xerror* pError;

	memset(&Desc, 0, sizeof(Desc));
	Desc.Kind = Kind;
	Desc.Domain = sDomain;
	Desc.Code = iCode;
	Desc.Operation = sOperation;
	Desc.Message = sMessage;
	Desc.Cause = pCause;
	pError = xrtErrorBuild(&Desc);
	if ( pError != NULL ) {
		__xrtErrorSetOwned(pError);
	}
}



/* 构建并安装同时保留稳定模块代码与原生系统代码的错误。 */
void __xrtErrorSetSystem(
	cstr sDomain,
	int32 iCode,
	cstr sOperation,
	int iSystemCode,
	cstr sMessage
)
{
	xerrordesc Desc;
	xerror* pError;

	memset(&Desc, 0, sizeof(Desc));
	Desc.Kind = __xrtSystemErrorKind(iSystemCode);
	Desc.Domain = sDomain;
	Desc.Code = iCode;
	Desc.SystemCode = iSystemCode;
	Desc.Operation = sOperation;
	Desc.Message = sMessage;
	pError = xrtErrorBuild(&Desc);
	if ( pError != NULL ) {
		__xrtErrorSetOwned(pError);
	}
}



/* 取得当前错误并包装，包装分配失败时保留原错误或内存错误。 */
void __xrtErrorWrapDetail(
	xerrkind DefaultKind,
	cstr sDomain,
	int32 iCode,
	cstr sOperation,
	cstr sMessage
)
{
	xerror* pCause = xrtTakeError();
	xerrkind Kind = pCause != NULL ?
		xrtErrorKind(pCause) : DefaultKind;

	__xrtErrorSetDetail(
		Kind,
		sDomain,
		iCode,
		sOperation,
		sMessage,
		pCause
	);
	if ( (xrtGetError() == NULL) && (pCause != NULL) ) {
		xrtSetError(pCause);
	}
	xrtErrorFree(pCause);
}



