{
	if ( pArray == NULL ) {
		__xrtErrorSetInvalidArgument();
		return false;
	}
	if ( pArray->ItemSize != sizeof(ptr) ) {
		__xrtErrorSetInvalidState();
		return false;
	}

	return true;
}



