			if (bPhased && !xrtOwnershipMutationBegin(pMutation)) abort();
			pView->Flags &= (uint16)~XRT_VALUE_FLAG_FINALIZING;
			pView->Flags |= XRT_VALUE_FLAG_BUSY;
