/* 读取网络字节序 24 位整数。 */
uint32 __xrtTlsRead24(const uint8* pData)
{
	return ((uint32)pData[0] << 16u) |
		((uint32)pData[1] << 8u) |
		(uint32)pData[2];
}



/* 写入网络字节序 24 位整数。 */
void __xrtTlsWrite24(uint8* pData, uint32 iValue)
{
	pData[0] = (uint8)(iValue >> 16u);
	pData[1] = (uint8)(iValue >> 8u);
	pData[2] = (uint8)iValue;
}



