		case XTLS_HANDSHAKE_NEW_SESSION_TICKET: return "new_session_ticket";
		case XTLS_HANDSHAKE_END_OF_EARLY_DATA: return "end_of_early_data";
		case XTLS_HANDSHAKE_ENCRYPTED_EXTENSIONS:
			return "encrypted_extensions";
