/* 返回 uint64 十进制线路文本长度。 */
size_t __xrtHttpUInt64Size(uint64 iValue)
{
	size_t iSize = 1;

	while ( iValue >= UINT64_C(10) ) {
		iValue /= UINT64_C(10);
		iSize++;
	}
	return iSize;
}



/* 写入无符号十进制线路文本。 */
size_t __xrtHttpUInt64Write(char* sOutput, uint64 iValue)
{
	size_t iSize = __xrtHttpUInt64Size(iValue);
	size_t i = iSize;

	do {
		sOutput[--i] = (char)(
			'0' + (char)(iValue % UINT64_C(10))
		);
		iValue /= UINT64_C(10);
	} while ( iValue != 0 );
	return iSize;
}



