/* Standalone XRT embedding: miniz.h is intentionally not vendored. */
#define MZ_DEFAULT_LEVEL 6
#define MZ_DEFAULT_STRATEGY 0
#define MZ_FILTERED 1
#define MZ_HUFFMAN_ONLY 2
#define MZ_RLE 3
#define MZ_FIXED 4

static mz_uint32 mz_adler32(mz_uint32 iAdler, const mz_uint8* pData, size_t iLen)
{
    mz_uint32 iA = iAdler & 0xFFFFu;
    mz_uint32 iB = (iAdler >> 16u) & 0xFFFFu;
    while (iLen > 0u)
    {
        size_t iBlock = iLen > 5552u ? 5552u : iLen;
        iLen -= iBlock;
        while (iBlock-- > 0u)
        {
            iA += *pData++;
            iB += iA;
        }
        iA %= 65521u;
        iB %= 65521u;
    }
    return (iB << 16u) | iA;
}

